<?php
if (!defined('ABSPATH')) { exit; }
if (!current_user_can(SPF_Roles::SALES) && !current_user_can('manage_options')) { wp_die(esc_html__('No tienes permisos para ver ventas.','sistema-para-farmacias')); }
global $wpdb;
$sales=SPF_Database::table('sales'); $items=SPF_Database::table('sale_items'); $customers=SPF_Database::table('customers');
$documents=SPF_Config::sales_documents(); $payments=SPF_Config::payment_methods();
$date_from=sanitize_text_field(wp_unslash($_GET['date_from']??wp_date('Y-m-01'))); $date_to=sanitize_text_field(wp_unslash($_GET['date_to']??wp_date('Y-m-d'))); $document=sanitize_key(wp_unslash($_GET['document_type']??'')); $payment=sanitize_key(wp_unslash($_GET['payment_method']??'')); $q=sanitize_text_field(wp_unslash($_GET['s']??'')); $view_sale_id=absint($_GET['view_sale']??0);
$where='s.created_at >= %s AND s.created_at <= %s'; $params=[$date_from.' 00:00:00',$date_to.' 23:59:59'];
if($document!==''){ $where.=' AND s.document_type = %s'; $params[]=$document; } if($payment!==''){ $where.=' AND s.payment_method = %s'; $params[]=$payment; }
if($q!==''){ $like='%'.$wpdb->esc_like($q).'%'; $where.=' AND (s.sale_number LIKE %s OR c.name LIKE %s OR c.business_name LIKE %s OR c.document_number LIKE %s OR si.product_name LIKE %s)'; array_push($params,$like,$like,$like,$like,$like); }
$list_sql="SELECT s.*,c.name customer_name,c.business_name,c.document_number,GROUP_CONCAT(CONCAT(si.product_name,' x',si.quantity) SEPARATOR ', ') products_sold FROM $sales s LEFT JOIN $customers c ON c.id=s.customer_id LEFT JOIN $items si ON si.sale_id=s.id WHERE $where GROUP BY s.id ORDER BY s.id DESC LIMIT 300";
$rows=$wpdb->get_results($wpdb->prepare($list_sql,...$params),ARRAY_A);
$summary_sql="SELECT COUNT(*) sales_count,COALESCE(SUM(t.total),0) total_sales,COALESCE(SUM(t.igv),0) total_tax,COALESCE(AVG(t.total),0) avg_ticket FROM (SELECT DISTINCT s.id,s.total,s.igv FROM $sales s LEFT JOIN $customers c ON c.id=s.customer_id LEFT JOIN $items si ON si.sale_id=s.id WHERE $where) t";
$summary=$wpdb->get_row($wpdb->prepare($summary_sql,...$params),ARRAY_A);
$detail=null; $detail_items=[]; if($view_sale_id>0){ $detail=$wpdb->get_row($wpdb->prepare("SELECT s.*,c.name customer_name,c.business_name,c.document_type customer_document_type,c.document_number,c.address,c.email,c.phone FROM $sales s LEFT JOIN $customers c ON c.id=s.customer_id WHERE s.id=%d",$view_sale_id),ARRAY_A); $detail_items=$wpdb->get_results($wpdb->prepare("SELECT * FROM $items WHERE sale_id=%d ORDER BY id ASC",$view_sale_id),ARRAY_A); }
$doc_label=function($code)use($documents){$m=$documents[$code]??$code;return is_array($m)?($m['label']??$code):$m;};
?>
<div class="wrap spf-wrap"><h1><?php esc_html_e('Ventas','sistema-para-farmacias'); ?></h1>
<div class="spf-cards"><div class="spf-card"><strong><?php echo esc_html((int)($summary['sales_count']??0)); ?></strong><span><?php esc_html_e('Ventas filtradas','sistema-para-farmacias'); ?></span></div><div class="spf-card"><strong><?php echo esc_html(SPF_Config::money($summary['total_sales']??0)); ?></strong><span><?php esc_html_e('Total vendido','sistema-para-farmacias'); ?></span></div><div class="spf-card"><strong><?php echo esc_html(SPF_Config::money($summary['total_tax']??0)); ?></strong><span><?php echo esc_html(SPF_Config::tax_name()); ?></span></div><div class="spf-card"><strong><?php echo esc_html(SPF_Config::money($summary['avg_ticket']??0)); ?></strong><span><?php esc_html_e('Ticket promedio','sistema-para-farmacias'); ?></span></div></div>
<div class="spf-panel"><h2><?php esc_html_e('Filtros','sistema-para-farmacias'); ?></h2><form method="get" class="spf-grid-form"><input type="hidden" name="page" value="spf-sales"><label><?php esc_html_e('Desde','sistema-para-farmacias'); ?><input type="date" name="date_from" value="<?php echo esc_attr($date_from); ?>"></label><label><?php esc_html_e('Hasta','sistema-para-farmacias'); ?><input type="date" name="date_to" value="<?php echo esc_attr($date_to); ?>"></label><label><?php esc_html_e('Documento','sistema-para-farmacias'); ?><select name="document_type"><option value=""><?php esc_html_e('Todos','sistema-para-farmacias'); ?></option><?php foreach($documents as $code=>$meta): ?><option value="<?php echo esc_attr($code); ?>" <?php selected($document,$code); ?>><?php echo esc_html(is_array($meta)?($meta['label']??$code):$meta); ?></option><?php endforeach; ?></select></label><label><?php esc_html_e('Pago','sistema-para-farmacias'); ?><select name="payment_method"><option value=""><?php esc_html_e('Todos','sistema-para-farmacias'); ?></option><?php foreach($payments as $code=>$label): ?><option value="<?php echo esc_attr($code); ?>" <?php selected($payment,$code); ?>><?php echo esc_html($label); ?></option><?php endforeach; ?></select></label><label><?php esc_html_e('Buscar','sistema-para-farmacias'); ?><input name="s" value="<?php echo esc_attr($q); ?>" placeholder="<?php esc_attr_e('Venta, cliente o producto','sistema-para-farmacias'); ?>"></label><div class="spf-form-actions"><button class="button button-primary"><?php esc_html_e('Filtrar','sistema-para-farmacias'); ?></button><a class="button" href="<?php echo esc_url(admin_url('admin.php?page=spf-sales')); ?>"><?php esc_html_e('Limpiar','sistema-para-farmacias'); ?></a></div></form></div>
<?php if($detail): ?><div class="spf-panel"><h2><?php echo esc_html(sprintf(__('Detalle de venta %s','sistema-para-farmacias'),$detail['sale_number'])); ?></h2><p><strong><?php esc_html_e('Cliente:','sistema-para-farmacias'); ?></strong> <?php echo esc_html($detail['business_name']?:$detail['customer_name']?:'—'); ?> · <?php echo esc_html(trim(($detail['customer_document_type']??'').' '.($detail['document_number']??''))); ?></p><p><strong><?php esc_html_e('Documento:','sistema-para-farmacias'); ?></strong> <?php echo esc_html($doc_label($detail['document_type'])); ?> · <strong><?php esc_html_e('Pago:','sistema-para-farmacias'); ?></strong> <?php echo esc_html($payments[$detail['payment_method']]??$detail['payment_method']); ?></p><div class="spf-table-scroll"><table class="widefat striped"><thead><tr><th><?php esc_html_e('Producto','sistema-para-farmacias'); ?></th><th><?php esc_html_e('Cantidad','sistema-para-farmacias'); ?></th><th><?php esc_html_e('Precio','sistema-para-farmacias'); ?></th><th><?php esc_html_e('Subtotal','sistema-para-farmacias'); ?></th><th><?php echo esc_html(SPF_Config::tax_name()); ?></th><th><?php esc_html_e('Total','sistema-para-farmacias'); ?></th></tr></thead><tbody><?php foreach($detail_items as $item): ?><tr><td><?php echo esc_html($item['product_name']); ?></td><td><?php echo esc_html($item['quantity']); ?></td><td><?php echo esc_html(SPF_Config::money($item['unit_price'])); ?></td><td><?php echo esc_html(SPF_Config::money($item['subtotal'])); ?></td><td><?php echo esc_html(SPF_Config::money($item['igv'])); ?></td><td><strong><?php echo esc_html(SPF_Config::money($item['total'])); ?></strong></td></tr><?php endforeach; ?></tbody></table></div></div><?php endif; ?>
<div class="spf-panel"><h2><?php esc_html_e('Listado de ventas','sistema-para-farmacias'); ?></h2><div class="spf-table-scroll"><table class="widefat striped"><thead><tr><th><?php esc_html_e('Número','sistema-para-farmacias'); ?></th><th><?php esc_html_e('Cliente','sistema-para-farmacias'); ?></th><th><?php esc_html_e('Productos','sistema-para-farmacias'); ?></th><th><?php esc_html_e('Documento','sistema-para-farmacias'); ?></th><th><?php esc_html_e('Pago','sistema-para-farmacias'); ?></th><th><?php echo esc_html(SPF_Config::tax_name()); ?></th><th><?php esc_html_e('Total','sistema-para-farmacias'); ?></th><th><?php esc_html_e('Fecha','sistema-para-farmacias'); ?></th><th></th></tr></thead><tbody><?php if(!$rows): ?><tr><td colspan="9"><?php esc_html_e('No hay ventas con estos filtros.','sistema-para-farmacias'); ?></td></tr><?php endif; ?><?php foreach($rows as $row): ?><tr><td><strong><?php echo esc_html($row['sale_number']); ?></strong></td><td><?php echo esc_html($row['business_name']?:$row['customer_name']?:'—'); ?></td><td><?php echo esc_html($row['products_sold']?:'—'); ?></td><td><?php echo esc_html($doc_label($row['document_type'])); ?></td><td><?php echo esc_html($payments[$row['payment_method']]??$row['payment_method']); ?></td><td><?php echo esc_html(SPF_Config::money($row['igv'])); ?></td><td><strong><?php echo esc_html(SPF_Config::money($row['total'])); ?></strong></td><td><?php echo esc_html($row['created_at']); ?></td><td><a class="button" href="<?php echo esc_url(admin_url('admin.php?page=spf-sales&view_sale='.(int)$row['id'])); ?>"><?php esc_html_e('Ver detalle','sistema-para-farmacias'); ?></a></td></tr><?php endforeach; ?></tbody></table></div></div></div>
